def HasCinfDerivAtT (w : ℝ → CinfT) (v : CinfT) (t : ℝ) : Prop :=
  ∀ (n : ℕ) (ε : ℝ), 0 < ε → ∃ η : ℝ, 0 < η ∧
    ∀ s : ℝ, |s - t| < η → ∀ x : ℝ,
      |iteratedDeriv n (fun y => (w s : ℝ → ℝ) y - (w t : ℝ → ℝ) y) x -
        (s - t) * iteratedDeriv n (v : ℝ → ℝ) x| ≤ ε * |s - t|

def IsRegFlowSolutionT (κ : ℝ) (w : ℝ → CinfT) : Prop :=
  ∀ t : ℝ, ∃ v : CinfT, HasCinfDerivAtT w v t ∧ ∀ x : ℝ, (v : ℝ → ℝ) x = regFlowRHS κ (w t : ℝ → ℝ) x

def IsDiffFlowSolutionT (κ : ℝ) (z : ℝ → CinfT) : Prop :=
  ∀ s : ℝ, ∃ v : CinfT, HasCinfDerivAtT z v s ∧ ∀ x : ℝ, (v : ℝ → ℝ) x = diffFlowRHS κ (z s : ℝ → ℝ) x

def recipGreenFluxT (κ₀ κ : ℝ) (w : ℝ → ℝ) (x : ℝ) : ℝ :=
  (1 / diagGreen κ₀ w x) *
    (w x + (4 * κ ^ 5 / (κ ^ 2 - κ₀ ^ 2)) * (diagGreen κ w x - 1 / (2 * κ)) -
      (4 * κ₀ ^ 5 / (κ ^ 2 - κ₀ ^ 2)) * (diagGreen κ₀ w x - 1 / (2 * κ₀)))

